  }
}

/* ========== 传统朱砂方印 ========== */
.chinese-seal {
  position: absolute;
  right: 22%;
  bottom: 22px;
  transform: rotate(-3deg);
  width: 92px;
  height: 30px;
  border: 1.5px solid #a82824;
