  padding: 1.5px;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transform-origin: center center;
  animation: stampIn 0.45s cubic-bezier(0.25, 1, 0.5, 1) forwards;
  animation-delay: 1.85s;
  pointer-events: none;
}

.seal-inner {
  width: 100%;
  height: 100%;
  background-color: #a82824;
  color: #FAF7F2;
  display: flex;
  align-items: center;
