  letter-spacing: 0.5px;
}

@keyframes stampIn {
  0% {
    opacity: 0;
    transform: scale(2.2) rotate(14deg);
    filter: blur(2px);
  }
  75% {
    opacity: 1;
    transform: scale(0.94) rotate(-6deg);
    filter: blur(0);
  }
  100% {
    opacity: 0.92;
    transform: scale(1) rotate(-4deg);
  }
}

